class Solution {
        public int uniquePaths(int[][] grid) {
                int m = grid.length;
                        int n = grid[0].length;
                                int MOD = 1_000_000_007;

                                        long[][] dp = new long[m][n];
                                                dp[0][0] = 1;

                                                        for (int i = 0; i < m; i++) {
                                                                    for (int j = 0; j < n; j++) {
                                                                                    if (dp[i][j] == 0) continue;

                                                                                                    // Try both moves: 0 for Right, 1 for Down
                                                                                                                    for (int dType = 0; dType < 2; dType++) {
                                                                                                                                        int[] nextPos = getJump(grid, i, j, dType);
                                                                                                                                                            if (nextPos != null) {
                                                                                                                                                                                    int tr = nextPos[0];
                                                                                                                                                                                                            int tc = nextPos[1];
                                                                                                                                                                                                                                    dp[tr][tc] = (dp[tr][tc] + dp[i][j]) % MOD;
                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                    return (int) dp[m - 1][n - 1];
                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                            private int[] getJump(int[][] grid, int r, int c, int dType) {
                                                                                                                                                                                                                                                                                                                    int m = grid.length;
                                                                                                                                                                                                                                                                                                                            int n = grid[0].length;
                                                                                                                                                                                                                                                                                                                                    int currR = r, currC = c;
                                                                                                                                                                                                                                                                                                                                            char d = (dType == 0) ? 'R' : 'D';

                                                                                                                                                                                                                                                                                                                                                    while (true) {
                                                                                                                                                                                                                                                                                                                                                                if (d == 'R') {
                                                                                                                                                                                                                                                                                                                                                                                int nr = currR;
                                                                                                                                                                                                                                                                                                                                                                                                int nc = currC + 1;
                                                                                                                                                                                                                                                                                                                                                                                                                if (nc >= n) return null;
                                                                                                                                                                                                                                                                                                                                                                                                                                if (grid[nr][nc] == 1) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                    currR = nr + 1;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                        currC = nc;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            d = 'D';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (currR >= m) return null;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                } else {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return new int[]{nr, nc};
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                } else { // d == 'D'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                int nr = currR + 1;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                int nc = currC;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (nr >= m) return null;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (grid[nr][nc] == 1) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    currR = nr;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        currC = nc + 1;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            d = 'R';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (currC >= n) return null;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                } else {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return new int[]{nr, nc};
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            // Handle consecutive mirror reflections
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        while (grid[currR][currC] == 1) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (d == 'D') {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            currC = currC + 1;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                d = 'R';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (currC >= n) return null;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    } else {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        currR = currR + 1;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            d = 'D';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (currR >= m) return null;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        return new int[]{currR, currC};
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
